<?php
namespace Tests\Feature;
use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class AuthenticationTest extends TestCase{use RefreshDatabase;public function test_guest_is_redirected_to_login():void{$this->get('/dashboard')->assertRedirect('/login');}public function test_active_user_can_login():void{$u=User::factory()->create(['password'=>'SecurePass123!','status'=>'active']);$this->post('/login',['email'=>$u->email,'password'=>'SecurePass123!'])->assertRedirect('/dashboard');$this->assertAuthenticatedAs($u);}public function test_inactive_user_cannot_login():void{$u=User::factory()->create(['password'=>'SecurePass123!','status'=>'inactive']);$this->post('/login',['email'=>$u->email,'password'=>'SecurePass123!'])->assertSessionHasErrors('email');$this->assertGuest();}public function test_authenticated_user_can_logout():void{$u=User::factory()->create();$this->actingAs($u)->post('/logout')->assertRedirect('/login');$this->assertGuest();}}
